<?php require_once __DIR__.'/../includes/admin-auth.php';require_admin(['super_admin','event_admin']);$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT r.*,u.name,u.email,u.mobile,e.title event_title,c.checked_in_at FROM registrations r JOIN users u ON u.id=r.user_id JOIN events e ON e.id=r.event_id LEFT JOIN checkins c ON c.registration_id=r.id WHERE r.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Registration not found');}$pageTitle='Registration details';require __DIR__.'/../includes/admin-layout.php'; ?><div class="panel"><h2><?=e($r['event_title'])?></h2><p class="muted">Registration <?=e($r['registration_code'])?></p><dl class="row"><dt class="col-sm-3">Participant</dt><dd class="col-sm-9"><?=e($r['name'])?></dd><dt class="col-sm-3">Email</dt><dd class="col-sm-9"><?=e($r['email'])?></dd><dt class="col-sm-3">Mobile</dt><dd class="col-sm-9"><?=e($r['mobile'])?></dd><dt class="col-sm-3">Entry code</dt><dd class="col-sm-9"><?=e($r['entry_code'])?></dd><dt class="col-sm-3">Registration status</dt><dd class="col-sm-9"><?=e($r['status'])?></dd><dt class="col-sm-3">Attendance</dt><dd class="col-sm-9"><?=$r['checked_in_at']?e($r['checked_in_at']):'Not checked in'?></dd></dl><a class="btn btn-outline-primary" href="registrations.php">Back to registrations</a></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
